// Writes src/server/db/migrations/index.gen.ts so the migrations are bundled into
// the executable. Run after `drizzle-kit generate` (see the db:generate script).
import { readdirSync, existsSync, writeFileSync } from "node:fs"
import { join } from "node:path"

const dir = join(import.meta.dir, "..", "src", "server", "db", "migrations")
const names = readdirSync(dir, { withFileTypes: true })
  .filter((entry) => entry.isDirectory() && existsSync(join(dir, entry.name, "migration.sql")))
  .map((entry) => entry.name)
  .sort()

const lines = [
  "// Generated by scripts/gen-migrations-index.ts. Do not edit.",
  ...names.map((name, i) => `import m${i} from "./${name}/migration.sql" with { type: "text" }`),
  "",
  "export const bundledMigrations: ReadonlyArray<{ readonly name: string; readonly sql: string }> = [",
  ...names.map((name, i) => `  { name: ${JSON.stringify(name)}, sql: m${i} },`),
  "]",
  ""
]
writeFileSync(join(dir, "index.gen.ts"), lines.join("\n"))
console.log(`Bundled ${names.length} migration(s).`)
